// Sound finite omega-threshold forward antichain; positive results require exact replay.
#include <bits/stdc++.h>
using namespace std;struct E{int f,t,a,c;vector<int>I,O;};struct N{int p;vector<int>r;int par,ei;bool live;};
int main(int ac,char**av){ifstream f(av[1]);int m,np,ne,ni,ng;f>>m>>np>>ne>>ni>>ng;int d=m*5;vector<int>initial(ni);for(auto&x:initial)f>>x;vector<vector<vector<int>>>goals(np);for(int j=0,p;j<ng;j++){f>>p;vector<int>r(d);for(auto&x:r)f>>x;goals[p].push_back(r);}vector<E>es(ne);vector<vector<int>>adj(np);for(int j=0;j<ne;j++){auto&e=es[j];f>>e.f>>e.t>>e.a>>e.c;e.I.resize(d);e.O.resize(m);for(auto&x:e.I)f>>x;for(auto&x:e.O)f>>x;assert(f&&e.c>=0&&e.c<=4);adj[e.f].push_back(j);}int cap=ac>2?stoi(av[2]):3;size_t limit=ac>3?stoull(av[3]):1000000;vector<N>ns;vector<vector<int>>B(np);size_t retired=0,cmp=0;int hit=-1;auto le=[&](const vector<int>&a,const vector<int>&b){cmp++;for(int i=0;i<d;i++)if(a[i]>b[i])return false;return true;};auto step=[&](const E&e,const vector<int>&x,vector<int>&y,int omega){for(int j=0;j<d;j++)if(x[j]!=omega&&x[j]<e.I[j])return false;for(int z=0;z<m;z++){int o=5*z;int a=x[o]==omega?omega:x[o]-e.I[o];int mn=a;for(int j=0;j<=e.c;j++)y[o+j]=a==omega?omega:min(omega,a+e.O[z]);for(int j=e.c+1;j<5;j++){int k=j-e.c,b=x[o+k]==omega?omega:x[o+k]-e.I[o+k];mn=min(mn,b);y[o+j]=mn;}}return true;};auto add=[&](int p,const vector<int>&r,int par,int ei){auto&v=B[p];for(int id:v)if(ns[id].live&&le(r,ns[id].r))return;for(int id:v)if(ns[id].live&&le(ns[id].r,r)){ns[id].live=false;retired++;}if(v.size()>32){vector<int>w;for(int id:v)if(ns[id].live)w.push_back(id);v.swap(w);}int id=ns.size();ns.push_back({p,r,par,ei,true});v.push_back(id);for(auto&g:goals[p]){bool ok=true;for(int j=0;j<d;j++)if(r[j]!=cap&&r[j]<g[j])ok=false;if(ok)hit=id;}};for(int p:initial)add(p,vector<int>(d),-1,-1);size_t next=ns.size();int depth=0;
for(size_t k=0;k<ns.size()&&hit<0;k++){if(k==next){depth++;next=ns.size();cerr<<"depth "<<depth<<" labels "<<ns.size()<<" live "<<ns.size()-retired<<" comparisons "<<cmp<<"\n";}if(!ns[k].live)continue;int p=ns[k].p;auto r=ns[k].r;for(int ei:adj[p]){auto&e=es[ei];vector<int>v(d);if(!step(e,r,v,cap))continue;add(e.t,v,k,ei);if(ns.size()>=limit){cout<<"status CAP labels "<<ns.size()<<" depth "<<depth<<"\n";return 0;}if(hit>=0)break;}}
if(hit<0){cout<<"status OMEGA_EXHAUSTED_NO_GOAL labels "<<ns.size()<<" live "<<ns.size()-retired<<" depth "<<depth<<"\n";if(ac>4){ofstream o(av[4]);o<<m<<" "<<np<<" "<<cap<<" "<<ns.size()-retired<<"\n";for(auto&n:ns)if(n.live){o<<n.p;for(auto x:n.r)o<<" "<<x;o<<"\n";}}return 0;}
cout<<"status OMEGA_MAY_WITNESS labels "<<ns.size()<<" depth "<<depth<<" saturation "<<cap<<"\n";vector<int>path;for(int u=hit;u>=0;u=ns[u].par)path.push_back(u);reverse(path.begin(),path.end());cout<<"start "<<ns[path[0]].p<<"\n";for(int u:path){auto&n=ns[u];if(n.par<0)continue;auto&e=es[n.ei];cout<<"EDGE "<<n.ei<<" "<<e.f<<" "<<e.t<<" "<<e.a;for(auto x:ns[n.par].r)cout<<" "<<x;cout<<"\n";}cout<<"goal "<<ns[hit].p;for(auto x:ns[hit].r)cout<<" "<<x;cout<<"\n";}
